/bin/bash -lc "python - <<'PY'
import math, os
paths={'all':'codex_output/galaxy_outputs/all_deseq2.tsv','subset':'codex_output/galaxy_outputs/subset_deseq2.tsv'}
counts={}
counts_padj={}
for name,path in paths.items():
    n=0; nadj=0; total=0; na=0
    with open(path) as f:
        for line in f:
            if not line.strip(): continue
            total += 1
            parts=line.rstrip('\\n').split('\\t')
            try:
                base=float(parts[1]); lfc=float(parts[2]); p=float(parts[4]); padj=float(parts[5]) if parts[5] not in ('NA','nan','') else math.nan
            except Exception:
                na += 1; continue
            if base > 10 and abs(lfc) > 1 and p < 0.05:
                n += 1
            if base > 10 and abs(lfc) > 1 and not math.isnan(padj) and padj < 0.05:
                nadj += 1
    counts[name]=n; counts_padj[name]=nadj
    print(name, 'rows', total, 'count_p', n, 'count_padj', nadj)
direction = 'increase' if counts['subset'] > counts['all'] else 'decrease' if counts['subset'] < counts['all'] else 'no change'
print('answer fields:', counts['all'], counts['subset'], direction)
os.makedirs('codex_output', exist_ok=True)
with open('codex_output/answer.txt','w') as f:
    f.write(f\"{counts['all']} {counts['subset']} {direction}\\n\")
PY
cat codex_output/answer.txt"

